#include "input_fixture.h"
#include <algorithm>
#include <cmath>
#include <future>
#include <iostream>

namespace {
using input_fixture::require;
void checks() {
    nolf::ClientInput input(input_fixture::controls()); const auto& api=nolf::ClientInput::functions(); require(api.ClearInput()==LT_NOTINITIALIZED,"input SDK active without scope"); const auto scope=input.activate();
    input_fixture::configure(input,"AddAction Forward 0; AddAction Jump 6; AddAction Axis1 -1; AddAction ZoomIn 61; AddAction ZoomOut 62; AddAction AxisYaw -10001; rangebind Keyboard 17 0 0 Forward; rangebind Keyboard 57 0 0 Jump; rangebind Mouse x-axis 0 0 Axis1; scale Mouse x-axis 0.01; rangebind Mouse z-axis -255 -0.1 ZoomOut 0.1 255 ZoomIn");
    require(input.logical_key(17)=='W' && input.logical_key(1)==27 && !input.logical_key(999),"input physical/logical keyboard mapping differs");
    auto event=input_fixture::key(17,true); auto frame=input.frame(std::span(&event,1)); require(frame.pressed==std::vector<unsigned>{0} && api.IsCommandOn(0),"held key action failed");
    frame=input.frame({}); require(frame.pressed.empty() && frame.released.empty() && api.IsCommandOn(0),"held key lost between frames");
    event.pressed=false; frame=input.frame(std::span(&event,1)); require(frame.released==std::vector<unsigned>{0} && !api.IsCommandOn(0),"key release action failed");
    std::array tap{input_fixture::key(17,true),input_fixture::key(17,false)}; frame=input.frame(tap); require(frame.pressed==std::vector<unsigned>{0} && api.IsCommandOn(0),"short tap lost within frame"); frame=input.frame({}); require(frame.released==std::vector<unsigned>{0},"short tap stuck");
    nolf::platform::InputEvent motion{}; motion.type=nolf::platform::InputType::mouse_motion; motion.x=90; motion.y=-25; input.frame(std::span(&motion,1)); float axes[3]={}; api.GetAxisOffsets(axes); require(std::abs(axes[0]-.9f)<.0001f && axes[1]==0,"mouse axis binding/scale failed"); input.frame({}); api.GetAxisOffsets(axes); require(axes[0]==0,"relative mouse axis retained old motion");
    motion.type=nolf::platform::InputType::wheel; motion.y=1; input.frame(std::span(&motion,1)); require(api.IsCommandOn(61) && !api.IsCommandOn(62),"wheel positive range failed"); input.frame({}); require(!api.IsCommandOn(61),"wheel range stuck"); motion.y=-1; input.frame(std::span(&motion,1)); require(api.IsCommandOn(62),"wheel negative range failed");
    require(input.toggle(6,true)==LT_OK,"toggle setup failed"); event=input_fixture::key(57,true); input.frame(std::span(&event,1)); require(api.IsCommandOn(6),"toggle press failed"); event.pressed=false; input.frame(std::span(&event,1)); require(api.IsCommandOn(6),"toggle release cleared latch"); event.pressed=true; input.frame(std::span(&event,1)); require(!api.IsCommandOn(6),"second toggle press failed"); require(input.toggle(6,true)==LT_OK,"toggle reset failed"); input.frame({}); require(!api.IsCommandOn(6),"toggle reset retriggered held key");
    require(input.toggle(256,true)==LT_INVALIDPARAMS,"invalid command accepted"); api.ClearInput(); event=input_fixture::key(17,true); input.frame(std::span(&event,1)); api.SetInputState(LTFALSE); frame=input.frame({}); require(frame.released==std::vector<unsigned>{0} && !api.IsCommandOn(0),"disabling input lost command release"); api.SetInputState(LTTRUE);
    event=input_fixture::key(17,true); input.frame(std::span(&event,1)); nolf::platform::InputEvent focus{}; focus.type=nolf::platform::InputType::focus; focus.pressed=false; frame=input.frame(std::span(&focus,1)); require(!api.IsCommandOn(0) && frame.released==std::vector<unsigned>{0},"focus loss left held commands"); focus.pressed=true; input.frame(std::span(&focus,1)); require(!api.IsCommandOn(0),"focus gain resurrected stale keyboard state");
    require(api.StartDeviceTrack(DEVICETYPE_KEYBOARD,2)==LT_OK,"device tracking start failed"); event=input_fixture::key(17,true); input.frame(std::span(&event,1)); require(!api.IsCommandOn(0),"tracking leaked normal commands"); DeviceInput tracked[2]{}; uint32 count=2; require(api.TrackDevice(tracked,&count)==LT_OK && count==1 && tracked[0].m_DeviceType==1 && tracked[0].m_KeyCode=='W' && std::string(tracked[0].m_ControlName)=="17" && tracked[0].m_InputValue==128,"tracked key identity/value differs");
    std::array overflow{input_fixture::key(17,false),input_fixture::key(57,true),input_fixture::key(57,false)}; input.frame(overflow); count=2; require(api.TrackDevice(tracked,&count)==LT_INPUTBUFFEROVERFLOW && count==2 && tracked[0].m_KeyCode==32,"tracking overflow lost bounded newest events"); require(api.EndDeviceTrack()==LT_OK && api.StartDeviceTrack(1,33)==LT_INVALIDPARAMS,"tracking stop/bounds failed");
    auto* objects=api.GetDeviceObjects(3); require(objects && objects->m_KeyCode==27 && objects->m_pNext && objects->m_RangeHigh==255,"device object metadata missing"); auto* bindings=api.GetDeviceBindings(1); require(bindings && bindings->pActionHead && bindings->pActionHead->nActionCode==0,"binding enumeration missing");
    { nolf::ClientInput other(input_fixture::controls()); const auto other_scope=other.activate(); api.FreeDeviceBindings(bindings); api.FreeDeviceObjects(objects); require(!api.IsCommandOn(0),"input scope did not switch owners"); }
    require(bindings->pActionHead->nActionCode==0 && objects->m_KeyCode==27,"foreign scope freed owned input snapshots"); api.FreeDeviceBindings(bindings); api.FreeDeviceObjects(objects); api.FreeDeviceBindings(reinterpret_cast<DeviceBinding*>(1));
    const auto before=input.config(); std::array<std::string_view,3> bad{"Mouse","x-axis","nan"}; require(input.command("scale",bad)==LT_INVALIDPARAMS && input.config()==before,"invalid binding transaction changed config");
    nolf::ClientInput restored(input_fixture::controls()); input_fixture::configure(restored,before); require(restored.config()==before,"input config round trip differs");
    input_fixture::configure(input,"rangebind Keyboard 17 0 0 \"*echo key\""); event=input_fixture::key(17,true); frame=input.frame(std::span(&event,1)); require(frame.console==std::vector<std::string>{"echo key"},"console binding press not deferred"); frame=input.frame({}); require(frame.console.empty(),"held console binding repeated");
    nolf::platform::GamepadState pad{}; pad.left_x=.5f; input.frame({},pad); input_fixture::configure(input,"enabledevice \"Joystick 1\"; rangebind \"Joystick 1\" x-axis 0 0 AxisYaw; rangescale \"Joystick 1\" x-axis 1 -1 1 0"); frame=input.frame({},pad); require(std::any_of(frame.variables.begin(),frame.variables.end(),[](const auto& item) { return item.first=="AxisYaw" && std::abs(item.second-.5f)<.0001f; }),"controller axis/range variable failed"); frame=input.frame({}); require(std::all_of(frame.variables.begin(),frame.variables.end(),[](const auto& item) { return item.second==0; }),"controller removal left held variable");
    require(std::async(std::launch::async,[&] { return api.ClearInput(); }).get()==LT_NOTINITIALIZED,"input scope leaked threads");
    auto owner=std::make_unique<nolf::ClientInput>(input_fixture::controls()); { const auto retained=owner->activate(); owner.reset(); require(api.ClearInput()==LT_OK,"input callback state died with host"); }
}
}
int main() { try { checks(); std::cout<<"Native input bindings, hold/tap/toggle/focus, axes, tracking, snapshots, config and ownership passed\n"; return 0; } catch (const std::exception& e) { std::cerr<<e.what()<<'\n'; return 1; } }
